// Extract Geo — robust pass-through + kvotvalidering
// Stödjer både:
//  - HTTP "Full Response": { body: { results: [...] , status, error_message } }
//  - HTTP "Body in root":  { results: [...] , status, error_message }
// Körs efter Merge så seed/query följer med.

const CONFIG = {
  failOn: ['OVER_QUERY_LIMIT'], // lägg ev. till: 'REQUEST_DENIED','INVALID_REQUEST'
};

const out = [];

for (const it of items) {
  const j = it.json || {};

  // Stöd för båda responslägena
  const body = j.body || j;
  const results = Array.isArray(body?.results) ? body.results : [];
  const status = (body?.status || '').toString().toUpperCase();
  const errMsg = body?.error_message || j?.error_message || null;

  // === Kvot/fel-validering ===
  if (CONFIG.failOn.includes(status)) {
    // Kasta fel så kvotflödet kan fånga/pausa
    throw new Error(
      `[Extract Geo] Geocoding failed with status=${status}` +
      (errMsg ? ` — ${errMsg}` : '')
    );
  }

  // Hämta koordinat om den finns
  const loc = results[0]?.geometry?.location;

  // Alias: säkerställ gemener om endast versaler finns
  const query = j.query ?? j.Query ?? null;
  const lang  = j.lang  ?? j.Lang  ?? null;
  const gl    = j.gl    ?? j.Gl    ?? null;

  // Seed: om saknas som objekt, bygg från toppnivå
  const seed = j.seed || {
    Industry: j.Industry,
    Country: j.Country,
    City: j.City,
    CityCountry: j.CityCountry,
    Row: j.Row,
    CityIndex: j.CityIndex,
    NextIndustryRow: j.NextIndustryRow,
    NextCityIndex: j.NextCityIndex,
  };

  if (!loc) {
    // Ingen geokoordinat hittad — lämna kvar item för felsökning
    out.push({
      json: {
        ...j,
        query, lang, gl,
        seed,
        geo: null,
        GeocodeStatus: status || null,
        _warn: 'No lat/lng found in Geocode response',
      },
    });
    continue;
  }

  out.push({
    json: {
      ...j,
      query, lang, gl,
      seed,
      geo: { lat: loc.lat, lng: loc.lng },
      GeocodeStatus: status || 'OK',
      GeocodePlaceId: results[0]?.place_id ?? null,
      GeocodeFormatted: results[0]?.formatted_address ?? null,
    },
  });
}

return out;

// n8n Code node — BUILD QUERIES (balanserad budget + varianter)

// ======= CONFIG =======
const CONFIG = {
  baseMaxVariants: 3,
  lang: 'sv',
  gl: 'se',
  sourceHint: 'serpapi|apify',
  strict: true,

  quotaMetricForVariants: 'text',
  quotaMetricForDetails:  'details',

  // Fallback om kvota saknas
  fallbackDetailsTotalCap: 200,

  // Planerat max
  pagesPlanned: 3,                 // vi kan nedjustera dynamiskt
  defaultDetailsCapPerPage: 5,
  minDetailsPerPage: 5,

  TEST_SEED: {
    Industry: 'Elektriker',
    Country:  'Sweden',
    City:     'Stockholm',
    CityCountry: 'Stockholm, Sweden',
    Row: 1, CityIndex: 0, NextIndustryRow: 1, NextCityIndex: 1,
  },
};

// ---------- helpers ----------
const nowIso = () => new Date().toISOString();
const clean  = (s) => (s ?? '').toString().trim();
const norm   = (s) => clean(s).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');

// Bransch → Google Places type (enkla regler – kan byggas ut)
const TYPE_RULES = [
  [/\b(elektriker|elinstallat|elfirma|el[-\s]?montör)\b/, 'electrician'],
  [/\b(rörmok|vvs)\b/, 'plumber'],
  [/\b(målare|måleri)\b/, 'painter'],
  [/\b(snickare|bygg|timmerman)\b/, 'carpenter'],
  [/\b(lås|låssmed|larm\W*installat|\blarm\b)\b/, 'locksmith'],
  [/\b(taklägg|tak|takfirma)\b/, 'roofing_contractor'],
  [/\b(hvac|ventilation|kyla|värmepump)\b/, 'hvac_contractor'],
  [/\b(städ|städning|städfirma)\b/, 'house_cleaning'],
];

function inferPlaceTypeFromIndustry(industry) {
  const s = norm(industry);
  for (const [re, type] of TYPE_RULES) if (re.test(s)) return type;
  return null;
}

// Läs kvot från "Gate Build (Quota ready)" om den finns
function readQuota(metricOverride) {
  let items = [];
  try { items = $items('Gate Build (Quota ready)'); } catch {}
  if (!items?.length) return null;

  const j = items[0]?.json || {};
  const caps = j.caps || {};

  const metric =
    (typeof metricOverride === 'string' && metricOverride) ||
    (typeof j.quotaMetric === 'string' && j.quotaMetric) ||
    CONFIG.quotaMetricForVariants || 'text';

  const kCapDaily   = `${metric}Daily`;
  const kUsed       = `${metric}Used`;
  const kUsedToday  = `${metric}UsedToday`;
  const kLimit      = `${metric}Limit`;
  const kCapGeneric = `${metric}Cap`;
  const kCapToday   = `${metric}CapToday`;
  const kRemaining  = `${metric}Remaining`;

  const num  = (x) => { const n = Number(x); return Number.isFinite(n) ? n : null; };
  const pick = (obj, keys) => { for (const k of keys) if (obj && obj[k] != null) return obj[k]; return null; };

  const cap =
    num(caps[kCapDaily]) ??
    num(pick(j, [kCapToday, `${metric}DailyCap`, kCapGeneric, `${metric}LimitToday`, kLimit])) ?? null;

  const used =
    num(j[kUsed]) ?? num(j[kUsedToday]) ??
    num(pick(j, ['usedText','textRequests'])) ?? null;

  let remaining = num(j[kRemaining]) ?? num(pick(j, ['remainingText'])) ?? null;
  if (remaining == null && cap != null && used != null) remaining = Math.max(0, cap - used);

  return { metric, cap: cap ?? null, used: used ?? null, remaining: remaining ?? null, raw: j };
}

function decideVariantCap(quota, fallback) {
  if (!quota) return fallback;
  const cap = quota.cap;
  let remaining = quota.remaining;
  if (remaining == null && cap != null && quota.used != null) remaining = Math.max(0, cap - quota.used);
  if (cap == null && remaining == null) return fallback;

  const effCap = cap ?? Math.max(remaining, 1);
  const effRem = remaining ?? Math.max(effCap * 0.2, 1);

  if (effRem <= 50) return 1;
  const ratio = effRem / effCap;
  if (ratio >= 0.5) return Math.min(4, CONFIG.baseMaxVariants);
  if (ratio >= 0.2) return Math.min(3, CONFIG.baseMaxVariants);
  if (ratio >= 0.1) return Math.min(2, CONFIG.baseMaxVariants);
  return 1;
}

function buildVariants(seed, maxVariants) {
  const industry = seed.Industry;
  const city = seed.City;
  const country = seed.Country;
  const cityCountry = seed.CityCountry;

  const sv = [
    `${industry} i ${city}, ${country}`,
    `bästa ${industry.toLowerCase()} ${city}`,
    `${industry} ${cityCountry}`,
    `${industry} företag ${city}`,
  ];
  const en = [
    `${industry} ${city}, ${country}`,
    `${industry} near ${city}`,
  ];

  const all = [...sv, ...en].filter(Boolean);
  return all.slice(0, Math.max(1, maxVariants));
}

// --------- robust seed-intag ---------
function toSeedObj(j0 = {}) {
  const j = j0 || {};
  const s = j.seed || {};
  const Industry = clean(j.Industry || s.Industry);
  const Country  = clean(j.Country  || s.Country);
  const City     = clean(j.City     || s.City);
  const CityCountry = clean(j.CityCountry || s.CityCountry || (City && Country ? `${City}, ${Country}` : ''));

  const seed = {
    Industry, Country, City, CityCountry,
    Row: (j.Row ?? s.Row ?? null),
    CityIndex: (j.CityIndex ?? s.CityIndex ?? null),
    NextIndustryRow: (j.NextIndustryRow ?? s.NextIndustryRow ?? null),
    NextCityIndex: (j.NextCityIndex ?? s.NextCityIndex ?? null),
  };
  const ok = !!seed.Industry && (!!seed.City || !!seed.CityCountry) && !!seed.Country;
  return { seed, ok };
}

// Hämta kandidater från: 1) input till noden, 2) "Input from WF1"
let candidates = ($input.all() || []).map(i => i.json || {});
try {
  const wfSeeds = ($items('Input from WF1') || []).map(i => i.json || {});
  candidates = candidates.concat(wfSeeds);
} catch {}

let seeds = [];
const seen = new Set();
for (const obj of candidates) {
  const { seed, ok } = toSeedObj(obj);
  if (!ok) continue;
  const key = `${seed.Industry}|${seed.CityCountry}|${seed.Row}|${seed.CityIndex}`;
  if (seen.has(key)) continue;
  seen.add(key);
  seeds.push(seed);
}

if (!seeds.length) {
  if (CONFIG.strict) {
    throw new Error('Build queries: Inget giltigt seed hittades på input (Industry, City/CityCountry, Country krävs).');
  }
  seeds = [CONFIG.TEST_SEED];
}

// --------- kvot → varianter ---------
const quotaForVariants = readQuota(CONFIG.quotaMetricForVariants);
let maxVariants        = decideVariantCap(quotaForVariants, CONFIG.baseMaxVariants);

// --------- budget för Place Details (balansering) ---------
const PAGE_SIZE = 20;
const SOFT_MIN  = 12;

const quotaForDetails      = readQuota(CONFIG.quotaMetricForDetails);
const detailsLeftTodayRaw  = Number(quotaForDetails?.remaining);
let   detailsLeftToday     = Number.isFinite(detailsLeftTodayRaw) ? Math.max(0, detailsLeftTodayRaw)
                                                                  : CONFIG.fallbackDetailsTotalCap;

// hur många seeds i denna körning?
let seedsPlanned = seeds.length;
try {
  const wf1Items = $items('Input from WF1') || [];
  if (wf1Items.length) seedsPlanned = wf1Items.length;
} catch {}

let P = CONFIG.pagesPlanned;   // kan nedjusteras
let V = maxVariants;

const idealDenom = Math.max(1, seedsPlanned * V * P);
let perPage = Math.floor(detailsLeftToday / idealDenom);
perPage = Math.min(PAGE_SIZE, Math.max(SOFT_MIN, perPage));

// prioritera fulla sidor (20) genom att skala ned P/V om budgeten är tajt
if (perPage < PAGE_SIZE) {
  // 1) färre sidor
  if (P > 2 && (perPage * 2) >= PAGE_SIZE) {
    P = 2;
    perPage = PAGE_SIZE;
  }
  // 2) färre varianter
  if (perPage < PAGE_SIZE) {
    const denomV1 = Math.max(1, seedsPlanned * 1 * P);
    const perPageIfV1 = Math.floor(detailsLeftToday / denomV1);
    if (V > 1 && perPageIfV1 >= PAGE_SIZE) {
      V = 1;
      perPage = PAGE_SIZE;
    }
  }
}

// om budgeten fortfarande inte räcker: respektera golv men gå inte över 20
perPage = Math.min(PAGE_SIZE, Math.max(SOFT_MIN, perPage));

// bygg varianter med ev. nedjusterat V
const variantCounts = seeds.map(s => buildVariants(s, V).length);
const totalVariants = Math.max(1, variantCounts.reduce((a,b)=>a+b, 0));

// --------- bygg ut ----------
function makeOutputItems(seed, variants, capPerPage) {
  const createdAt = nowIso();
  const placeType = inferPlaceTypeFromIndustry(seed.Industry);
  const wantTypes = placeType ? [placeType, 'establishment'] : [];

  return variants.map((q, idx) => {
    const lang = idx <= 2 ? CONFIG.lang : 'en';
    return {
      json: {
        Query: q, query: q,
        VariantIndex: idx,
        Lang: lang, lang,
        Gl: CONFIG.gl, gl: CONFIG.gl,
        Source: CONFIG.sourceHint,
        CreatedAt: createdAt,

        Industry: seed.Industry,
        Country:  seed.Country,
        City:     seed.City,
        CityCountry: seed.CityCountry,
        Row: seed.Row,
        CityIndex: seed.CityIndex,
        NextIndustryRow: seed.NextIndustryRow,
        NextCityIndex:   seed.NextCityIndex,

        seed: { ...seed },

        // budget-signaler nedströms
        _detailsCap: Math.max(1, Number(capPerPage) || CONFIG.defaultDetailsCapPerPage),
        _detailsCapPerPage: Math.max(1, Number(capPerPage) || CONFIG.defaultDetailsCapPerPage),
        _pagesPlanned: P,
        _variantsPlanned: V,

        PlaceType: placeType,
        WantTypes: wantTypes,

        // Viktigt: ge bredare träffbild i TextSearch
        useType: false,

        _buildQueries: true,
      },
    };
  });
}

let out = [];
let idxSeed = 0;
for (const s of seeds) {
  const vCount = variantCounts[idxSeed++] || V;
  const variants = buildVariants(s, vCount);
  out = out.concat(makeOutputItems(s, variants, perPage));
}

return out;

// ===== Explode Search Results =====

// Hårdkap för hur många vi *max* vill skicka vidare (används bara om _detailsCap inte finns)
const DEFAULT_DETAILS_CAP = 10;

const CONFIG = {
  failOn:  ['OVER_QUERY_LIMIT', 'REQUEST_DENIED'],
  softZero: ['ZERO_RESULTS'],
};

const out = [];

for (const it of items) {
  const j = it.json || {};

  // Skip-flagga från tidigare gren
  if (j._skipTextSearch) continue;

  // Stöd: full HTTP-respons (body) eller redan-nerlyft body
  const body   = j.body || j;
  const status = String(body?.status || '').toUpperCase();
  const page   = j._page ?? 1;

  // Status-hantering
  if (CONFIG.failOn.includes(status)) {
    throw new Error(`[Explode] TextSearch failed: status=${status}${body?.error_message ? ' — ' + body.error_message : ''}`);
  }
  if (CONFIG.softZero.includes(status)) {
    continue; // 0 items vidare
  }

  // Resultlistan
  const all = Array.isArray(body?.results) ? body.results : [];

  // Cap: använd item-specifik _detailsCap, annars DEFAULT. Om cap <= 0 => ta alla.
  const rawCap = Number(j._detailsCap);
  const cap = Number.isFinite(rawCap) ? rawCap : DEFAULT_DETAILS_CAP;
  const picked = cap > 0 ? all.slice(0, cap) : all;

  // Alias/seed/geo
  const query = j.query ?? j.Query ?? null;
  const lang  = j.lang  ?? j.Lang  ?? null;
  const gl    = j.gl    ?? j.Gl    ?? null;

  const seed  = j.seed || {
    Industry: j.Industry, Country: j.Country, City: j.City,
    CityCountry: j.CityCountry, Row: j.Row, CityIndex: j.CityIndex,
    NextIndustryRow: j.NextIndustryRow, NextCityIndex: j.NextCityIndex,
  };

  const geo   = j.geo ?? null;

  // Ett item per träff
  for (const r of picked) {
    out.push({
      json: {
        // kontext
        seed, geo, query, lang, gl,
        _page: page,
        _textsearch_status: status || null,

        // snabbåtkomstfält
        place_id: r.place_id ?? null,
        name: r.name ?? null,
        rating: r.rating ?? null,
        reviews: r.user_ratings_total ?? null,
        address: r.formatted_address ?? null,
        types: Array.isArray(r.types) ? r.types : [],

        // praktisk Maps-URL
        maps_url: r.place_id ? `https://www.google.com/maps/place/?q=place_id:${r.place_id}` : null,

        // hela råträffen (ifall vi behöver mer senare)
        result: r,
      }
    });
  }
}

return out;

// Normalize → fält för RAW & VALIDATED (robust)
function norm(v){ return (v ?? '').toString().trim(); }
function onlyDigitsPlus(s){ return norm(s).replace(/[^0-9+]/g, ''); }
function hostFromUrl(u){
  let s = norm(u);
  if (!s) return '';
  try {
    if (!/^https?:\/\//i.test(s)) s = 'http://' + s;
    return new URL(s).hostname.toLowerCase().replace(/^www\./, '');
  } catch { return ''; }
}

return items.map(it => {
  const j = it.json || {};

  // Flexibla källor (Explode/Details/HTTP kan ha olika former)
  const details = j?.details?.result || j?.details || j?.result || {};

  // Länkar
  const website  = norm(details.website || j.Website || j.website || '');
  const domain   = hostFromUrl(website);
  const gmapsUrl = norm(details.url || j.url || j.GoogleMapsUrl || j.googlemapsurl || j.maps_url || '');

  // Telefon — stöd för både Google-fields och våra egna guard-fält
  const phoneRawSource =
    details.international_phone_number ||
    details.formatted_phone_number ||
    details.phone_raw ||
    j.details?.phone_raw ||
    j.PhoneRaw || j.Phone || j.phone || '';

  const phoneRaw  = norm(phoneRawSource);
  const phoneNorm = onlyDigitsPlus(details.phone_norm || phoneRaw);

  const out = {
    // Id & namn
    PlaceId: j.PlaceId || j.place_id || details.place_id || (j.result?.place_id || j.details?.place_id) || '',
    Name:    j.Name    || j.name     || details.name     || (j.result?.name || ''),

    // Adress/typer/betyg
    Address:
      j.Address || j.address ||
      details.address || details.formatted_address || details.vicinity ||
      j.result?.formatted_address || j.result?.vicinity || '',
    Types:   Array.isArray(j.Types) ? j.Types : (details.types || j.result?.types || []),
    Rating:  (j.Rating ?? j.rating ?? details.rating ?? j.result?.rating ?? null),
    Reviews: (j.Reviews ?? j.reviews ?? details.user_ratings_total ?? j.result?.user_ratings_total ?? null),

    // Länkar
    GoogleMapsUrl: gmapsUrl,
    Website: website,
    Domain:  domain,

    // Telefon (rå + normaliserad)
    Phone: phoneNorm,
    PhoneRaw: phoneRaw,
    PhoneNormalized: phoneNorm,

    // Seed-kontekst
    Industry:     (j.seed?.Industry     ?? j.Industry     ?? ''),
    Country:      (j.seed?.Country      ?? j.Country      ?? ''),
    City:         (j.seed?.City         ?? j.City         ?? ''),
    CityCountry:  (j.seed?.CityCountry  ?? j.CityCountry  ?? ''),

    // Övrigt
    _page: j._page,
    _textsearch_status: j._textsearch_status,
    CreatedAt: new Date().toISOString(),

    // Snabba flaggor
    HasWebsite: !!(website || domain),
    HasPhone:   phoneNorm.length >= 6,
  };

  return { json: out };
});

const seen = new Set();
const out = [];

for (const it of items) {
  const j = it.json || {};
  const pid = j.place_id || j.result?.place_id;

  // Saknar place_id? hoppa över
  if (!pid) continue;

  if (seen.has(pid)) continue; // redan skickad
  seen.add(pid);

  out.push({ json: j });
}

return out;

// Validated-kriterier
const REQUIRE_WEBSITE = true;  // true = kräver sajt; false = sajt ELLER telefon

function norm(v){ return (v ?? '').toString().trim(); }
function onlyDigitsPlus(s){ return norm(s).replace(/[^0-9+]/g, ''); }

return items.filter(it => {
  const j = it.json || {};

  // Läs primärt top-level (Normalize lade dessa), men backa till details vid behov
  const website = norm(j.Website || j.website || j.details?.website || '');
  const domain  = norm(j.Domain  || j.domain  || '');
  const phone   = onlyDigitsPlus(j.Phone || j.PhoneNormalized || j.phone || j.details?.phone_norm || j.details?.phone_raw || '');

  const hasWebsite = !!(website || domain || j.HasWebsite === true);
  const hasPhone   = (j.HasPhone === true) || (phone.length >= 6);

  // Policy: kräver sajt? annars sajt eller telefon
  const ok = REQUIRE_WEBSITE ? hasWebsite : (hasWebsite || hasPhone);

  return ok;
});

// Init Quota Caps — dagliga tak m. säkerhetsmarginal + kompatibla alias

const now = new Date();
const daysInMonth = new Date(now.getFullYear(), now.getMonth() + 1, 0).getDate();

// Justera vid behov
const SAFETY = 0.80; // 80% av gratisnivån som säkerhetsmarginal

// Gratis/månad enligt nuvarande modell (ändra här om du vill finjustera)
const MONTHLY = {
  text:    5000,  // Places Text Search (Pro)
  details: 5000,  // Place Details (Pro)
  geocode: 10000, // Geocoding (Essentials)
};

// Räkna fram dagliga tak (avrundat nedåt) + se till att minsta tak är 1
function dailyCap(monthly) {
  return Math.max(1, Math.floor((monthly / daysInMonth) * SAFETY));
}

const caps = {
  textDaily:    dailyCap(MONTHLY.text),
  detailsDaily: dailyCap(MONTHLY.details),
  geocodeDaily: dailyCap(MONTHLY.geocode),
};

// Returnera även alias/flat keys för maximal kompatibilitet
return [{
  json: {
    monthKey: now.toISOString().slice(0, 7), // "YYYY-MM"
    daysInMonth,
    safety: SAFETY,

    monthly: { ...MONTHLY },

    // Primär kapslad struktur
    caps: { ...caps },

    // Kompatibla alias som andra noder letar efter
    textDailyCap:    caps.textDaily,
    detailsDailyCap: caps.detailsDaily,
    geocodeDailyCap: caps.geocodeDaily,

    // Meta
    generatedAt: now.toISOString(),
  }
}];

// Bygg/behåll dagens rad till Quota-bladet
const today    = new Date().toISOString().slice(0,10); // YYYY-MM-DD
const monthKey = today.slice(0,7);                      // YYYY-MM

// Plocka ev. befintlig rad för "today" från Quota → Read (All)
const rows = (items || []).map(it => it.json || {});
const existing = rows.find(r => String(r.Day) === today) || null;

const out = {
  Day: today,
  MonthKey: monthKey,
  textUsed:    Number(existing?.textUsed    || 0),
  detailsUsed: Number(existing?.detailsUsed || 0),
  geocodeUsed: Number(existing?.geocodeUsed || 0),
};

return [{ json: out }];

// Tar CityCountry (fallback City + Country) och bygger ett säkert address-fält
const city = ($json.City || '').toString().trim();
const country = ($json.Country || '').toString().trim();
const cityCountry = ($json.CityCountry || '').toString().trim() || [city, country].filter(Boolean).join(', ');

// Throw om vi saknar nödvändigt under strict-läge
if (!cityCountry) {
  throw new Error('Prep Geocode Input: Saknar City/Country för geokodning.');
}

return [
  {
    json: {
      ...$json,
      AddressForGeocode: cityCountry, // t.ex. "Karlshamn, Sweden"
      GeocodeLang: 'sv',
      GeocodeRegion: 'se',
    },
  },
];

return [{
  json: {
    ...$json,
    _skipTextSearch: true,
    __reason: 'no-geo'  // för enklare felsök/loggning
  }
}];

const j = $json || {};
const hasGeo = !!(j.geo && typeof j.geo.lat === 'number' && typeof j.geo.lng === 'number');
return [{ json: { ...j, hasGeo } }];

const sum = { text: 0, details: 0, geocode: 0 };

for (const it of items) {
  const q = it.json?.__quota || {};
  sum.text    += Number(q.text    || 0);
  sum.details += Number(q.details || 0);
  sum.geocode += Number(q.geocode || 0);
}

// Bygg en enda rad som nästa steg kan merge:a med "Ensure Today (build)"
return [{
  json: {
    Day: new Date().toISOString().slice(0,10),  // "YYYY-MM-DD"
    textUsed: sum.text,
    detailsUsed: sum.details,
    geocodeUsed: sum.geocode,
  }
}];

// Quota Totals — robust läsning av bas + delta
// - delta kommer från föregående nod (Quota Δ Sum) via $input
// - bas hämtas säkert från "Ensure Today (build)" med try/catch

function safeFirstJson(nodeName) {
  try {
    const arr = $items(nodeName);
    if (Array.isArray(arr) && arr.length) return arr[0].json || {};
  } catch (e) {
    // noden kan saknas vid vissa körningar – ignorera
  }
  return {};
}

const today = new Date().toISOString().slice(0, 10);

// 1) Delta från Quota Δ Sum (inkommande item)
const delta = ($input.first() && $input.first().json) || {};

// 2) Bas från Ensure Today (build)
const base = safeFirstJson('Ensure Today (build)');

const asNum = (v) => Number(v || 0);

// 3) Slå ihop
const day = base.Day || delta.Day || today;
const monthKey = base.MonthKey ?? (day ? day.slice(0, 7) : today.slice(0, 7));

return [{
  json: {
    Day: day,
    MonthKey: monthKey,

