const aggUsed = Math.max(usedText, usedDetails, usedGeo);
const aggRemaining = Math.max(0, (isFinite(aggCap) ? aggCap : 0) - aggUsed);

// 4) Output (många kompatibla nycklar så Build queries hittar dem)
