// Paginate TextSearch — single output med rutt-taggning
// _route: 'this'  → denna sidans resultat → Explode → Keep Unique → Details
// _route: 'next'  → nästa sidans request (med pagetoken) → Wait ~2700 ms → Places Text Search

const MAX_PAGES = 3;
const out = [];

const arr = Array.isArray(items) ? items : [];
for (const it of arr) {
  const j = (it && it.json) ? it.json : {};
  const body = j.body || j;
  const next = body && body.next_page_token ? body.next_page_token : null;

  const page = Number.isFinite(j._page) ? Number(j._page) : 1;
  const status = String(body?.status || '').toUpperCase();

  // 1) Denna sidans payload (utan token)
  out.push({
    json: {
      ...j,
      paginate: undefined,
      _page: page,
      _textsearch_status: status,
      _route: 'this',
    },
  });

  // 2) Nästa sidans request (med token) – om tillgänglig
  if (next && page < MAX_PAGES) {
    out.push({
      json: {
        ...j,                          // behåll seed/query/_detailsCap m.m.
        paginate: { token: next },     // ← Places Text Search läser denna
        _page: page + 1,
        _route: 'next',
      },
    });
  }
}

return out;

