// Details Inspect — sätt _needsRetry för transienta fel, max 2 försök
const MAX_RETRIES = 2;

// Statusar i body.status som brukar lösa sig vid retry
const RETRYABLE_STATUS = new Set([
  'OVER_QUERY_LIMIT',
  'UNKNOWN_ERROR',
  'RESOURCE_EXHAUSTED'
]);

return items.map(it => {
  const j = it.json || {};
  const body = j.body || j;

  // HTTP-kod från noden (varierar med credential/nod)
  const httpCode = Number(j.code || j.statusCode || body.code || 0);
  const status   = String(body.status || j.status || '').toUpperCase();

  const hasResult = !!(body.result || j.result);
  const curRetry  = Number(j._retry_details || 0);

  // Transienta fel: HTTP 429 eller “retryable” status OCH vi har inte fått resultat
  const isTransient =
    httpCode === 429 || (RETRYABLE_STATUS.has(status) && !hasResult);

  const needsRetry = isTransient && curRetry < MAX_RETRIES;

  return {
    json: {
      ...j,
      _details_status: status || (hasResult ? 'OK' : 'UNKNOWN'),
      _http_details: httpCode,
      _needsRetry: needsRetry,
      _retry_details: curRetry // bumpas i Bump Retry
    }
  };
});

// Bump Retry — öka försök & beräkna backoff
return items.map(it => {
  const j = it.json || {};
  const n = Number(j._retry || 0) + 1;                    // nästa försök
  const delay = Math.min(60000, Math.round(2000 * Math.pow(1.8, n - 1))); // 2s, 3.6s, 6.5s, 11.7s, 21.0s ...
  return { json: { ...j, _retry: n, _retryDelayMs: delay } };
});

// Kvalitetsflaggor och små saneringar för Website/Domain/Phone.
// OBS: vi filtrerar INTE här – bara sätter flaggor + ett enkelt score.

function norm(v){ return (typeof v === 'string' ? v.trim() : ''); }
function cleanPhone(p){
  let s = norm(p);
  if (!s) return '';
  // ta bort allt utom siffror och +
  s = s.replace(/[^\d+]/g, '');
  // 00 -> + (internationellt prefix)
  if (s.startsWith('00')) s = '+' + s.slice(2);
  return s;
}
function hostFromUrl(u){
  let s = norm(u);
  if(!s) return '';
  try{
    if(!/^https?:\/\//i.test(s)) s = 'http://' + s;
    const h = new URL(s).hostname.toLowerCase();
    return h.replace(/^www\./, '');
  }catch{ return ''; }
}

